/**
 * Data + helpers for app/open-source-licenses.tsx. The JSON is generated by
 * scripts/generate-licenses.mjs from the installed packages.
 */
import licenses from '@/content/open-source-licenses.json';

export type OpenSourceLicense = { name: string; version: string; license: string };

export const OPEN_SOURCE_LICENSES: OpenSourceLicense[] = licenses as OpenSourceLicense[];

/** npm page for a package; scoped names keep their "@scope/" segment. */
export function npmPackageUrl(name: string): string {
  return `https://www.npmjs.com/package/${name.split('/').map(encodeURIComponent).join('/')}`;
}
